CREATE TABLE public.workspace_members (workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,user_id uuid NOT NULL,role public.org_role NOT NULL CHECK(role<>'owner'),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,user_id));
GRANT SELECT ON public.workspace_members TO authenticated; GRANT ALL ON public.workspace_members TO service_role;
ALTER TABLE public.workspace_members ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.has_workspace_role(_workspace uuid,_min public.org_role DEFAULT 'viewer') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspaces w JOIN public.organization_members om ON om.org_id=w.org_id JOIN public.organizations o ON o.id=w.org_id WHERE w.id=_workspace AND om.user_id=auth.uid() AND o.status='active' AND public.role_rank(om.role)>=public.role_rank(_min) AND (om.role='owner' OR EXISTS(SELECT 1 FROM public.workspace_members wm WHERE wm.workspace_id=w.id AND wm.user_id=auth.uid() AND public.role_rank(wm.role)>=public.role_rank(_min)))) $$;
REVOKE ALL ON FUNCTION public.has_workspace_role(uuid,public.org_role) FROM public,anon; GRANT EXECUTE ON FUNCTION public.has_workspace_role(uuid,public.org_role) TO authenticated;
CREATE POLICY "authorized members read workspace assignments" ON public.workspace_members FOR SELECT TO authenticated USING(public.has_workspace_role(workspace_id,'viewer') OR EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=workspace_id AND public.has_org_role(w.org_id,'owner')));
INSERT INTO public.workspace_members(workspace_id,user_id,role) SELECT w.id,m.user_id,m.role FROM public.workspaces w JOIN public.organization_members m ON m.org_id=w.org_id WHERE m.role<>'owner' ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.set_workspace_member(_workspace uuid,_user uuid,_role public.org_role DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid; member_role public.org_role; BEGIN SELECT org_id INTO oid FROM public.workspaces WHERE id=_workspace FOR UPDATE; IF oid IS NULL OR NOT public.has_org_role(oid,'owner') THEN RAISE EXCEPTION 'Only organization owners can assign workspace access'; END IF; SELECT role INTO member_role FROM public.organization_members WHERE org_id=oid AND user_id=_user; IF member_role IS NULL OR member_role='owner' OR _role='owner' THEN RAISE EXCEPTION 'Invalid workspace member'; END IF; IF _role IS NOT NULL AND public.role_rank(_role)>public.role_rank(member_role) THEN RAISE EXCEPTION 'Workspace role cannot exceed organization role'; END IF; IF _role IS NULL THEN DELETE FROM public.workspace_members WHERE workspace_id=_workspace AND user_id=_user; ELSE INSERT INTO public.workspace_members(workspace_id,user_id,role) VALUES(_workspace,_user,_role) ON CONFLICT(workspace_id,user_id) DO UPDATE SET role=excluded.role; END IF; INSERT INTO public.audit_logs(org_id,actor_id,action,target_type,target_id,metadata) VALUES(oid,auth.uid(),'workspace.access_changed','workspace',_workspace::text,jsonb_build_object('user_id',_user,'role',_role)); END $$;
REVOKE ALL ON FUNCTION public.set_workspace_member(uuid,uuid,public.org_role) FROM public,anon; GRANT EXECUTE ON FUNCTION public.set_workspace_member(uuid,uuid,public.org_role) TO authenticated;
CREATE OR REPLACE FUNCTION public.workspace_creator_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND public.has_org_role(NEW.org_id,'admin') THEN INSERT INTO public.workspace_members(workspace_id,user_id,role) VALUES(NEW.id,auth.uid(),'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER workspace_creator_access AFTER INSERT ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.workspace_creator_access();
CREATE OR REPLACE FUNCTION public.workspace_access_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.org_id IS DISTINCT FROM OLD.org_id THEN RAISE EXCEPTION 'Workspace organization is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER workspace_org_immutable BEFORE UPDATE ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.workspace_access_guard();
CREATE POLICY "workspace scope read" ON public.workspaces AS RESTRICTIVE FOR SELECT TO authenticated USING(public.has_workspace_role(id,'viewer'));
CREATE POLICY "workspace scope update" ON public.workspaces AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.has_workspace_role(id,'admin')) WITH CHECK(public.has_workspace_role(id,'admin'));
CREATE POLICY "workspace scope delete" ON public.workspaces AS RESTRICTIVE FOR DELETE TO authenticated USING(public.has_workspace_role(id,'owner'));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['business_profiles','business_facts','documents','conversations','agent_runs','approvals','workspace_extensions'] LOOP EXECUTE format('CREATE POLICY "workspace authorized read" ON public.%I AS RESTRICTIVE FOR SELECT TO authenticated USING(public.has_workspace_role(workspace_id,''viewer''))',t); EXECUTE format('CREATE POLICY "workspace authorized insert" ON public.%I AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.has_workspace_role(workspace_id,''member''))',t); EXECUTE format('CREATE POLICY "workspace authorized update" ON public.%I AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.has_workspace_role(workspace_id,''member'')) WITH CHECK(public.has_workspace_role(workspace_id,''member''))',t); EXECUTE format('CREATE POLICY "workspace authorized delete" ON public.%I AS RESTRICTIVE FOR DELETE TO authenticated USING(public.has_workspace_role(workspace_id,''member''))',t); END LOOP; END $$;
CREATE POLICY "workspace authorized connections" ON public.connector_connections AS RESTRICTIVE FOR ALL TO authenticated USING(workspace_id IS NULL OR public.has_workspace_role(workspace_id,'viewer')) WITH CHECK(workspace_id IS NULL OR public.has_workspace_role(workspace_id,'admin'));
CREATE POLICY "workspace authorized messages" ON public.messages AS RESTRICTIVE FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND public.has_workspace_role(c.workspace_id,'viewer'))) WITH CHECK(EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND public.has_workspace_role(c.workspace_id,'member')));
CREATE POLICY "workspace authorized usage read" ON public.ai_usage_events AS RESTRICTIVE FOR SELECT TO authenticated USING(run_id IS NULL OR EXISTS(SELECT 1 FROM public.agent_runs r WHERE r.id=run_id AND public.has_workspace_role(r.workspace_id,'viewer')) OR public.has_platform_role('platform_owner'));
CREATE POLICY "workspace authorized usage insert" ON public.ai_usage_events AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(run_id IS NULL OR EXISTS(SELECT 1 FROM public.agent_runs r WHERE r.id=run_id AND r.org_id=ai_usage_events.org_id AND public.has_workspace_role(r.workspace_id,'member')));
CREATE OR REPLACE FUNCTION public.document_path_access(_path text,_min public.org_role) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid; wid uuid; BEGIN BEGIN oid:=split_part(_path,'/',1)::uuid; wid:=split_part(_path,'/',2)::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN false; END; RETURN EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=wid AND w.org_id=oid) AND public.has_workspace_role(wid,_min); END $$;
REVOKE ALL ON FUNCTION public.document_path_access(text,public.org_role) FROM public,anon; GRANT EXECUTE ON FUNCTION public.document_path_access(text,public.org_role) TO authenticated;
CREATE POLICY "workspace storage read" ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(bucket_id<>'documents' OR public.document_path_access(name,'viewer'));
CREATE POLICY "workspace storage upload" ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id<>'documents' OR public.document_path_access(name,'member'));
CREATE POLICY "workspace storage update" ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING(bucket_id<>'documents' OR public.document_path_access(name,'member')) WITH CHECK(bucket_id<>'documents' OR public.document_path_access(name,'member'));
CREATE POLICY "workspace storage delete" ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(bucket_id<>'documents' OR public.document_path_access(name,'admin'));
CREATE OR REPLACE FUNCTION public.create_workspace(_org uuid,_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE wid uuid; lim jsonb; n int; BEGIN PERFORM 1 FROM public.organizations WHERE id=_org FOR UPDATE; IF NOT public.has_org_role(_org,'admin') THEN RAISE EXCEPTION 'forbidden'; END IF; IF length(trim(_name)) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'Workspace name must contain 1 to 120 characters'; END IF; lim:=public.org_entitlement(_org,'workspaces'); IF lim IS NULL THEN RAISE EXCEPTION 'Workspace entitlement not configured'; END IF; SELECT count(*) INTO n FROM public.workspaces WHERE org_id=_org; IF lim<>'null'::jsonb AND n>=(lim::text)::int THEN RAISE EXCEPTION 'Your workspace limit has been reached'; END IF; INSERT INTO public.workspaces(org_id,name) VALUES(_org,trim(_name)) RETURNING id INTO wid; INSERT INTO public.business_profiles(org_id,workspace_id) VALUES(_org,wid); INSERT INTO public.audit_logs(org_id,actor_id,action,target_type,target_id) VALUES(_org,auth.uid(),'workspace.created','workspace',wid::text); RETURN wid; END $$;
REVOKE ALL ON FUNCTION public.create_workspace(uuid,text) FROM public,anon; GRANT EXECUTE ON FUNCTION public.create_workspace(uuid,text) TO authenticated; REVOKE INSERT ON public.workspaces FROM authenticated;
CREATE OR REPLACE FUNCTION public.decide_approval(_id uuid,_approve boolean,_note text) RETURNS public.approval_status LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.approvals; ns public.approval_status; BEGIN SELECT * INTO a FROM public.approvals WHERE id=_id FOR UPDATE; IF a.id IS NULL OR NOT public.has_workspace_role(a.workspace_id,'admin') THEN RAISE EXCEPTION 'forbidden'; END IF; IF a.status<>'pending' THEN RAISE EXCEPTION 'approval is not pending'; END IF; ns:=CASE WHEN _approve THEN 'approved'::public.approval_status ELSE 'rejected'::public.approval_status END; UPDATE public.approvals SET status=ns,decided_by=auth.uid(),decided_at=now(),decision_note=left(_note,1000) WHERE id=_id; INSERT INTO public.audit_logs(org_id,actor_id,action,target_type,target_id,metadata) VALUES(a.org_id,auth.uid(),'approval.'||ns::text,'approval',_id::text,jsonb_build_object('capability',a.capability_key)); RETURN ns; END $$;
CREATE OR REPLACE FUNCTION public.confirm_business_profile(_workspace uuid,_profile jsonb,_facts jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid; f jsonb; fid uuid; BEGIN SELECT org_id INTO oid FROM public.workspaces WHERE id=_workspace; IF oid IS NULL OR NOT public.has_workspace_role(_workspace,'member') THEN RAISE EXCEPTION 'forbidden'; END IF; IF jsonb_typeof(_facts) IS DISTINCT FROM 'array' OR jsonb_array_length(_facts) NOT BETWEEN 1 AND 24 OR jsonb_typeof(_profile) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'invalid profile'; END IF; IF length(coalesce(_profile->>'website',''))>500 OR length(coalesce(_profile->>'description',''))>3000 THEN RAISE EXCEPTION 'profile too long'; END IF; IF coalesce((_profile->>'monthly_budget_eur')::numeric,0)<0 OR coalesce((_profile->>'monthly_budget_eur')::numeric,0)>100000000 THEN RAISE EXCEPTION 'invalid budget'; END IF; FOR f IN SELECT value FROM jsonb_array_elements(_facts) LOOP IF length(coalesce(f->>'key','')) NOT BETWEEN 1 AND 120 OR length(coalesce(f->>'value','')) NOT BETWEEN 1 AND 3000 OR coalesce(f->>'source_type','') NOT IN ('user','website','ai_assumption') OR coalesce((f->>'confidence')::numeric,0) NOT BETWEEN 0 AND 1 THEN RAISE EXCEPTION 'invalid fact'; END IF; END LOOP; FOR f IN SELECT value FROM jsonb_array_elements(_facts) LOOP SELECT id INTO fid FROM public.business_facts WHERE workspace_id=_workspace AND key=f->>'key' AND source_ref IS NOT DISTINCT FROM f->>'source_ref' ORDER BY created_at DESC LIMIT 1; IF fid IS NULL THEN INSERT INTO public.business_facts(org_id,workspace_id,key,value,source_type,source_ref,confidence,verified) VALUES(oid,_workspace,f->>'key',f->>'value',(f->>'source_type')::public.fact_source,f->>'source_ref',(f->>'confidence')::numeric,coalesce((f->>'verified')::boolean,false)); ELSE UPDATE public.business_facts SET value=f->>'value',confidence=(f->>'confidence')::numeric,verified=coalesce((f->>'verified')::boolean,false) WHERE id=fid; END IF; END LOOP; INSERT INTO public.business_profiles(org_id,workspace_id,website,description,industry,business_model,offerings,audiences,markets,competitors,objectives,monthly_budget_eur,onboarding_completed_at) VALUES(oid,_workspace,nullif(_profile->>'website',''),nullif(_profile->>'description',''),nullif(_profile->>'industry',''),nullif(_profile->>'business_model',''),coalesce(_profile->'offerings','[]'),coalesce(_profile->'audiences','[]'),coalesce(_profile->'markets','[]'),coalesce(_profile->'competitors','[]'),coalesce(_profile->'objectives','[]'),(_profile->>'monthly_budget_eur')::numeric,now()) ON CONFLICT(workspace_id) DO UPDATE SET website=excluded.website,description=excluded.description,industry=excluded.industry,business_model=excluded.business_model,offerings=excluded.offerings,audiences=excluded.audiences,markets=excluded.markets,competitors=excluded.competitors,objectives=excluded.objectives,monthly_budget_eur=excluded.monthly_budget_eur,onboarding_completed_at=now(); INSERT INTO public.audit_logs(org_id,actor_id,action,target_type,target_id,metadata) VALUES(oid,auth.uid(),'business_profile.confirmed','workspace',_workspace::text,jsonb_build_object('fact_count',jsonb_array_length(_facts))); END $$;
REVOKE ALL ON FUNCTION public.confirm_business_profile(uuid,jsonb,jsonb) FROM public,anon; GRANT EXECUTE ON FUNCTION public.confirm_business_profile(uuid,jsonb,jsonb) TO authenticated;